item.content:encoded:
.elementor-section.elementor-section.elementor-section-boxed>.elementor-container {
    max-width: 1140px;
}

span.mega-indicator {
    float: right;
}

.fa-map-marker:before {
    content: "\f041" !important;
}

.reign-header-top .container {
    max-width: 1150px;
}

.widget_product_search .woocommerce-product-search button:before {
    color: #333;
}

.reign-header-top {
	  font-size: 13px;
    padding: 10px 0;
}
.widget_product_search .woocommerce-product-search button {
	color: #434f5a;
}
.reign-header-top {
	font-size: 14px;
}
.reign-header-top .header-top-right a {
	margin: 0 8px;
}
.reign-fallback-header .rg-hdr-v4-row-2 {
    background: #fff !important;
    box-shadow: 0 0 0;
    border-top: 1px solid #eee;
}

.rda-sidebar-mega-menu #mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 {
	background: #fff !important;
	z-index: 99;
}

/* product-thumbnail */

.product-thumbnail li {
    list-style: none;
    background: #fff;
    margin-top: 10px;
    padding: 10px;
    position: relative;
}
.product-thumbnail img {
    max-width: 90px;
    margin-right: 10px;
}

.fa, .fas {
   font-family: "FontAwesome" !important;
   font-weight: 900;
}
.primary-menu > li > a {
	    padding: 0 0.5rem;
}

